static const Node *const kTrees[kTreeCount] = {kTree0, kTree1, kTree2, kTree3, kTree4, kTree5, kTree6, kTree7, kTree8, kTree9, kTree10, kTree11, kTree12, kTree13, kTree14, kTree15, kTree16, kTree17, kTree18, kTree19, kTree20, kTree21, kTree22, kTree23, kTree24, kTree25, kTree26, kTree27, kTree28, kTree29, kTree30, kTree31, kTree32, kTree33, kTree34, kTree35, kTree36, kTree37, kTree38, kTree39};

inline uint8_t predict(const float features[kFeatureCount]) {
  uint16_t votes[kClassCount] = {};
  for (uint8_t treeIndex = 0; treeIndex < kTreeCount; treeIndex++) {
    const Node *tree = kTrees[treeIndex];
    int16_t nodeIndex = 0;
    while (tree[nodeIndex].feature >= 0) {
      const Node &node = tree[nodeIndex];
      nodeIndex = features[node.feature] <= node.threshold ? node.left : node.right;
    }
    votes[tree[nodeIndex].value]++;
  }
  uint8_t best = 0;
  for (uint8_t label = 1; label < kClassCount; label++) {
    if (votes[label] > votes[best]) {
      best = label;
    }
  }
  return best;
}

